/**
 * Audio loader chunk — the ONLY import site of the real Babylon `Sound`
 * (kept off the first-paint bundle). Mirrors src/engine/gltfChunk.ts.
 *
 * This module is a REGISTERED CHUNK MANIFEST MODULE (see MANIFEST_MODULES in
 * tooling/check-shader-imports.mjs, `chunk: true`) and is loaded EXCLUSIVELY
 * via dynamic `import()` from buildWorld — only when a world actually contains
 * an `audio` entity. A STATIC import of this module from anywhere would pull
 * the ~24 KB Babylon WebAudio engine (`audioEngine`, `audioSceneComponent`,
 * `webAudioParameterComponent`/`webAudioBaseSubGraph`/`abstractSoundSource`)
 * into the main bundle at first paint — which a SILENT world (the Model
 * Explorer launch case, pure-primitive demos) never uses. Rule 3 of the lint
 * (`npm run lint`) fails on any static import of this file; type-only imports
 * (`import type`) are erased and legal.
 *
 * The side-effect variant (`@babylonjs/core/Audio/sound`, not `sound.pure`)
 * registers the audio engine + scene component. It adds NO shaders/materials
 * — the shader-manifest invariant is untouched — so this chunk contributes no
 * entries to the vite optimizeDeps mirror.
 */
import { Sound } from '@babylonjs/core/Audio/sound';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { SoundFactory, SoundFactoryOptions, SpatialSound } from './audioEntity';
import { log } from '../logging/runtimeLog';
import { isHeld, worldAccessOf } from '../net/worldRequests';

/**
 * The real-Sound factory (constructed with `autoplay:false` — v4 owns play
 * timing via the gesture gate). Shape matches `SoundFactory` so buildWorld can
 * hand it to `createAudioEntity` exactly like a test fake.
 */
export const createSound: SoundFactory = (name, url, scene, options): SpatialSound => {
  // Babylon is never given the address to fetch: the browser would ask for it
  // with the page's cookies. The sound is made empty and handed the bytes,
  // fetched as the scene's world may fetch them. A `data:` address is bytes
  // the page already holds, and goes to Babylon as it is.
  const sound = new Sound(name, isHeld(url) ? url : null, scene, null, {
    autoplay: false,
    loop: options.loop,
    volume: options.volume,
    spatialSound: options.spatialSound,
    // Only when given (a declared audio entity keeps Babylon's defaults).
    ...(options.refDistance !== undefined ? { refDistance: options.refDistance } : {}),
    ...(options.maxDistance !== undefined ? { maxDistance: options.maxDistance } : {}),
    ...(options.rolloffFactor !== undefined ? { rolloffFactor: options.rolloffFactor } : {}),
    ...(options.distanceModel !== undefined ? { distanceModel: options.distanceModel } : {}),
  });
  if (!isHeld(url)) {
    worldAccessOf(scene)
      .fetch(url)
      .then((response) => (response.ok ? response.arrayBuffer() : Promise.reject(new Error(`HTTP ${response.status}`))))
      .then(
        // The loader behind `setAudioBuffer` is the constructor's own, which decodes a file's bytes as it does a decoded buffer.
        (bytes) => sound.setAudioBuffer(bytes as unknown as AudioBuffer),
        (err) => log.warn(`[webverse] sound '${name}' failed to load ${url}: ${err instanceof Error ? err.message : String(err)}`),
      );
  }
  if (options.cone) aimCone(name, sound, options.cone);
  return sound as unknown as SpatialSound;
};

const DEGREES_PER_RADIAN = 180 / Math.PI;

/**
 * A directional cone on a positioned (unattached) sound. The legacy `Sound`
 * sets a direction only for a sound attached to a node, and only while it
 * plays, so the world direction goes straight to the AudioV2 sound it wraps:
 * the same property its attached path writes. When that is not reachable the
 * sound stays omnidirectional: a cone facing Babylon's default (+X) would be
 * worse than none. `setDirectionalCone` takes full angles in degrees.
 */
function aimCone(name: string, sound: Sound, cone: NonNullable<SoundFactoryOptions['cone']>): void {
  const spatial = (sound as unknown as { _soundV2?: { spatial?: { orientation: Vector3 } } })._soundV2?.spatial;
  if (!spatial) {
    log.warn(`[webverse] sound '${name}': its cone's direction cannot be set; it plays in every direction`);
    return;
  }
  spatial.orientation = new Vector3(cone.direction.x, cone.direction.y, cone.direction.z);
  sound.setDirectionalCone(cone.innerAngle * DEGREES_PER_RADIAN, cone.outerAngle * DEGREES_PER_RADIAN, cone.outerGain);
}

/** The module shape buildWorld consumes (injectable for unit tests). */
export type AudioChunkModule = {
  createSound: SoundFactory;
};
